tool_and_message_events.command:
/bin/bash -lc 'set -eu
review_dir=$(mktemp -d "$PWD/.desk-review.XXXXXX")
printf '"'%s\\n' \""'$review_dir"
cp -R release/. "$review_dir/"
cd "$review_dir"
npm install --cache "$review_dir/.npm-cache" --offline --ignore-scripts --no-audit --no-fund ../vendor/hono-4.13.19.tgz
node -p "require('"'./node_modules/hono/package.json').version\"
npm test
node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import app from './app.mjs';

const cases = [
  { name: 'valid', id: 'a7', session: 'day', status: 200, body: { id: 'a7', title: 'Harbor' }, steps: 'dispatch,session,read' },
  { name: 'no session', id: 'a7', status: 401, body: { error: 'sign_in' }, steps: 'dispatch,session' },
  { name: 'missing card', id: 'missing', session: 'day', status: 404, body: { error: 'not_found' }, steps: 'dispatch,session,read' },
  { name: 'invalid card', id: 'b4', session: 'day', status: 502, body: { error: 'invalid_record' }, steps: 'dispatch,session,read,error' },
];
let failures = 0;
for (const entry of cases) {
  const path = '/desk/' + entry.id;
  const headers = entry.session ? { 'x-shift': entry.session } : {};
  try {
    const response = await app.request(new Request('http://localhost' + path, { method: 'GET', headers }));
    const contentType = response.headers.get('content-type');
    const raw = await response.text();
    console.log(JSON.stringify({ case: entry.name, path, status: response.status, raw, steps: response.headers.get('x-desk-steps'), contentType }));
    assert.equal(response.status, entry.status);
    assert.deepEqual(JSON.parse(raw), entry.body);
    assert.equal(response.headers.get('x-desk-steps'), entry.steps);
    assert.match(contentType, /"'^application'"\\/json(?:;|"'$)/i);
  } catch (error) {
    failures++;
    console.error(error);
  }
}
console.log('"'Contract cases passed: ' + (cases.length - failures) + '/' + cases.length);
process.exitCode = failures > 0 ? 1 : 0;
NODE
"

